-- Vexus Lock anti-hook (contexto: layer-decode)
-- Checa se funcoes e metamethods sensiveis ainda sao closures/valores
-- nativos (C) antes de prosseguir. Substituir um deles por uma closure
-- Lua e a forma mais comum de interceptar e vazar o script/segredo
-- antes da execucao normal, ou de "dumpar" o payload decodificado.
local function _vxIsNativeClosure(fn)
    if typeof(fn) ~= "function" then return true end -- nao e funcao, nao ha o que checar aqui
    local ok, result = pcall(function()
        if iscclosure then return iscclosure(fn) end
        if is_synapse_function then return not is_synapse_function(fn) end
        return nil -- executor sem introspeccao de closure: nao bloqueia, so nao valida
    end)
    if not ok or result == nil then return true end
    return result
end

-- Confere se o proprio script esta rodando como topo de chunk
-- (loadstring/execute do executor), e nao "requerido"/encapsulado por
-- outro script que so quer capturar o retorno (return f()) pra dumpar
-- o payload ja decodificado. checkcaller() e exposto pela maioria dos
-- executores modernos; quando ausente, o check e pulado sem bloquear.
local function _vxCheckCaller()
    local ok, result = pcall(function()
        if checkcaller then return checkcaller() end
        return nil
    end)
    if not ok or result == nil then return true end
    return result
end

-- Le um metamethod via getrawmetatable sem disparar __metatable/erros,
-- pra comparar contra a implementacao nativa esperada.
local function _vxGetMetamethod(obj, name)
    local ok, mt = pcall(function()
        if getrawmetatable then return getrawmetatable(obj) end
        return nil
    end)
    if not ok or not mt then return nil end
    local ok2, fn = pcall(function() return rawget(mt, name) end)
    if not ok2 then return nil end
    return fn
end

local function _vxCheckHooks()
    local HttpService = game:GetService("HttpService")
    local candidates = {
        { name = "loadstring/load", fn = (loadstring or load) },
        { name = "game.HttpGet", fn = game.HttpGet },
        { name = "HttpService.RequestAsync", fn = HttpService.RequestAsync },
        { name = "bit32.bxor", fn = bit32 and bit32.bxor },
        { name = "string.char", fn = string.char },
        { name = "string.byte", fn = string.byte },
        { name = "table.concat", fn = table.concat },
        { name = "getrawmetatable", fn = getrawmetatable },
        { name = "game.__namecall", fn = _vxGetMetamethod(game, "__namecall") },
        { name = "game.__index", fn = _vxGetMetamethod(game, "__index") },
    }
    for _, c in ipairs(candidates) do
        if c.fn and not _vxIsNativeClosure(c.fn) then
            error("Vexus Lock: ambiente comprometido detectado (" .. c.name .. " parece ter sido hookado/interceptado). Execucao abortada por seguranca.", 0)
        end
    end
    if not _vxCheckCaller() then
        error("Vexus Lock: execucao fora do contexto esperado (script parece estar sendo encapsulado/requerido por outro, um padrao comum de dump). Execucao abortada por seguranca.", 0)
    end
end

_vxCheckHooks()

